contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool unused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // parameter `unused` is present to satisfy the requirement of at least one parameter
        uint beforeTest = address(this).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: either the call reverted or this contract's balance is >= beforeTest
        assert(reverted || address(this).balance >= beforeTest);
    }
    receive() external payable { }
}

